CREATE OR REPLACE FUNCTION private.admin_notice (
  actor         uuid,
  actor_session uuid,
  operation     text,
  target_id     bigint DEFAULT NULL::bigint,
  request_id    uuid   DEFAULT NULL::uuid,
  payload       jsonb  DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
  prior private.notice_requests%rowtype;
  arguments jsonb := jsonb_build_object('id',target_id,'payload',payload);
  result jsonb;
  page integer;
  title text;
  body text;
  inbox_body text;
  inbox_only boolean;
  comments_closed boolean;
begin
  perform private.assert_moderator(actor, actor_session);
  if operation = 'list' then
    page := coalesce((payload->>'page')::integer, 1);
    if page not between 1 and 100000 then raise exception 'invalid_notice_page' using errcode='22023'; end if;
    return jsonb_build_object(
      'total',(select count(*) from private.posts p where p.notice_title is not null and p.deleted_at is null),
      'rows',(select coalesce(jsonb_agg(private.notice_json(p.id) order by p.created_at desc,p.id desc),'[]')
        from (select p.id,p.created_at from private.posts p where p.notice_title is not null and p.deleted_at is null
          order by p.created_at desc,p.id desc limit 20 offset (page-1)*20) p)
    );
  end if;
  if operation = 'get' then
    result := private.notice_json(target_id);
    if result is null or (result->>'is_deleted')::boolean then raise exception 'notice_not_found' using errcode='P0002'; end if;
    return result;
  end if;
  if operation is null or operation not in ('create','update','visibility','delete') or request_id is null then
    raise exception 'invalid_notice_request' using errcode='22023';
  end if;
  -- 응답 유실·동시 재시도도 최초 요청의 결과를 돌려준다. 같은 UUID의 본문 변경은 거부한다.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(request_id::text,0));
  select * into prior from private.notice_requests r where r.request_id=admin_notice.request_id;
  if found then
    if prior.admin_id<>actor or prior.operation<>operation or prior.arguments<>arguments then
      raise exception 'notice_request_conflict' using errcode='P0001';
    end if;
    return prior.result;
  end if;
  if operation in ('create','update') then
    if jsonb_typeof(payload->'title') is distinct from 'string' or
       jsonb_typeof(payload->'body') is distinct from 'string' or
       jsonb_typeof(payload->'inbox_body') is distinct from 'string' or
       jsonb_typeof(payload->'inbox_only') is distinct from 'boolean' or
       jsonb_typeof(payload->'comments_closed') is distinct from 'boolean' then
      raise exception 'invalid_notice_content' using errcode='22023';
    end if;
    title := normalize(btrim(payload->>'title'),NFC);
    body := normalize(btrim(replace(replace(payload->>'body',E'\r\n',E'\n'),E'\r',E'\n')),NFC);
    inbox_body := normalize(btrim(payload->>'inbox_body'),NFC);
    inbox_only := (payload->>'inbox_only')::boolean;
    comments_closed := (payload->>'comments_closed')::boolean;
    if private.char_count(title) not between 1 and 100 or title ~ E'[\r\n]' or
       private.char_count(body) not between 1 and 10000 or body !~ '[^[:space:]]' or
       private.char_count(inbox_body)>200 then
      raise exception 'invalid_notice_content' using errcode='22023';
    end if;
  end if;
  if operation = 'create' then
    if target_id is not null then raise exception 'invalid_notice_request' using errcode='22023'; end if;
    insert into private.posts(author_id,type,content,creation_request_id,notice_title,notice_inbox_body,
      notice_inbox_only,notice_comments_closed)
    values(actor,'post',body,request_id,title,inbox_body,inbox_only,comments_closed) returning * into target;
  else
    select * into target from private.posts p where p.id=target_id and p.notice_title is not null for update;
    if not found or target.deleted_at is not null then raise exception 'notice_not_found' using errcode='P0002'; end if;
    if payload->>'revision' is distinct from target.notice_revision::text then
      raise exception 'notice_revision_conflict' using errcode='P0001';
    end if;
    if operation = 'update' then
      update private.posts set content=body,notice_title=title,notice_inbox_body=inbox_body,
        notice_inbox_only=inbox_only,notice_comments_closed=comments_closed,notice_revision=notice_revision+1
      where id=target.id;
    elsif operation = 'visibility' then
      if jsonb_typeof(payload->'is_visible') is distinct from 'boolean' then
        raise exception 'invalid_notice_visibility' using errcode='22023';
      end if;
      update private.posts set hidden_at=case when (payload->>'is_visible')::boolean then null else now() end,
        hidden_by=case when (payload->>'is_visible')::boolean then null else actor end,
        notice_revision=notice_revision+1 where id=target.id;
    else
      update private.posts set deleted_at=now(),notice_revision=notice_revision+1 where id=target.id;
    end if;
  end if;
  result := private.notice_json(target.id);
  insert into private.notice_requests(request_id,admin_id,operation,arguments,result)
  values(request_id,actor,operation,arguments,result);
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION private.community_post_json (
  target_post_id bigint,
  is_preview     boolean
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select case when is_preview then jsonb_build_object(
    'id', p.id::text, 'type', p.type, 'created_at', p.created_at,
    'content', split_part(replace(p.content, E'\r', ''), E'\n', 1),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'position', i.position, 'image_url', i.image_url) order by i.position)
      from private.post_products i where i.post_id = p.id), '[]'::jsonb)
  ) else jsonb_build_object(
    'id', p.id::text, 'type', p.type, 'created_at', p.created_at, 'ends_at', p.ends_at,
    'server_now', now(), 'content', p.content, 'is_mine', p.author_id = (select auth.uid()),
    'author_nickname', author.nickname,
    'notice', case when p.notice_title is not null then jsonb_build_object(
      'title',p.notice_title,'comments_closed',p.notice_comments_closed) else null end,
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'position', i.position, 'name', i.name, 'brand', i.brand, 'price', i.price,
      'url', i.url, 'image_url', i.image_url) order by i.position)
      from private.post_products i where i.post_id = p.id), '[]'::jsonb),
    'like_count', (select count(*) from private.post_likes l where l.post_id = p.id),
    'is_liked', exists(select 1 from private.post_likes l where l.post_id = p.id and l.user_id = (select auth.uid())),
    'comment_count', (select count(*) from private.comments c where c.post_id = p.id
      and c.deleted_at is null and c.hidden_at is null and private.community_author_visible(c.author_id)
        and private.community_content_visible('comment', c.id)),
    'my_choice', (select v.choice from private.vote_responses v where v.post_id = p.id and v.user_id = (select auth.uid())),
    'buy_count', case when p.type = 'vote' and (p.author_id = (select auth.uid()) or p.ends_at <= now() or
      exists(select 1 from private.vote_responses v where v.post_id = p.id and v.user_id = (select auth.uid())))
      then (select count(*) from private.vote_responses v where v.post_id = p.id and v.choice = 'buy') else null end,
    'not_count', case when p.type = 'vote' and (p.author_id = (select auth.uid()) or p.ends_at <= now() or
      exists(select 1 from private.vote_responses v where v.post_id = p.id and v.user_id = (select auth.uid())))
      then (select count(*) from private.vote_responses v where v.post_id = p.id and v.choice = 'not') else null end
  ) end
  from private.posts p join public.profiles author on author.id = p.author_id
  where p.id = target_post_id;
$function$;

CREATE OR REPLACE FUNCTION private.create_comment (
  target_post_id  bigint,
  comment_content text,
  request_id      uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
  viewer_id uuid := (select auth.uid());
  existing private.comments%rowtype;
  clean_content text;
  anon_number integer;
  saved_id bigint;
begin
  target := private.lock_community_post_for_write(target_post_id);
  if target.notice_title is not null and target.notice_comments_closed then
    raise exception 'notice_comments_closed' using errcode='P0001';
  end if;
  if request_id is null then raise exception 'invalid_request_id' using errcode = '22023'; end if;
  select * into existing from private.comments where author_id = viewer_id and creation_request_id = request_id;
  if found then
    if existing.post_id <> target.id then raise exception 'invalid_request_id' using errcode = '22023'; end if;
    if existing.deleted_at is not null or existing.hidden_at is not null then
      raise exception 'comment_not_found' using errcode = '42501';
    end if;
    return private.community_comment_json(existing.id);
  end if;
  clean_content := private.normalize_comment_content(comment_content);
  if viewer_id <> target.author_id then
    select number into anon_number from private.post_anon_numbers where post_id = target.id and user_id = viewer_id;
    if anon_number is null then
      update private.posts set next_anon_number = next_anon_number + 1 where id = target.id
      returning next_anon_number - 1 into anon_number;
      insert into private.post_anon_numbers(post_id, user_id, number) values (target.id, viewer_id, anon_number);
    end if;
  end if;
  insert into private.comments(post_id, author_id, content, creation_request_id)
  values (target.id, viewer_id, clean_content, request_id) returning id into saved_id;
  return private.community_comment_json(saved_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.delete_community_post (
  target_post_id bigint
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  viewer_id uuid := (select auth.uid());
  target private.posts%rowtype;
begin
  if viewer_id is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  perform private.assert_can_write_community();
  -- RPT-006: 기간 제한 중에는 본인 게시글 삭제도 차단한다.
  select * into target from private.posts where id = target_post_id and author_id = viewer_id for update;
  if not found then raise exception 'post_not_found' using errcode = '42501'; end if;
  if target.notice_title is not null then raise exception 'admin_required' using errcode='42501'; end if;
  if target.deleted_at is not null then return; end if;
  update private.posts set deleted_at = now() where id = target.id;
  update private.comments set deleted_at = now() where post_id = target.id and deleted_at is null;
  if target.type = 'vote' then delete from private.vote_responses where post_id = target.id; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_app_notifications (
  after_created_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  after_key        text                     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare viewer_id uuid := private.notification_viewer();
begin
  if (after_created_at is null)<>(after_key is null) or
    (after_key is not null and after_key !~ '^(notice:)?[1-9][0-9]{0,18}$') then
    raise exception 'invalid_notification_cursor' using errcode='22023';
  end if;
  return (with entries as (
    select n.id::text as key,n.created_at,jsonb_build_object(
      'id',n.id::text,'title',n.title,'body',n.body,'created_at',n.created_at,
      'post_id',p.id::text,'post_type',p.type,'is_post_available',
      p.deleted_at is null and p.hidden_at is null and private.community_author_visible(p.author_id)
      and private.community_content_visible('post',p.id)) as data
    from private.notifications n join private.posts p on p.id=n.post_id
    where n.recipient_id=viewer_id and n.created_at>now()-interval '30 days'
      and (n.actor_id is null or private.notification_actor_visible(viewer_id,n.actor_id))
    union all
    select 'notice:'||p.id::text,p.created_at,jsonb_build_object(
      'id','notice:'||p.id::text,'title',p.notice_title,
      'body',coalesce(nullif(p.notice_inbox_body,''),p.content),'created_at',p.created_at,
      'post_id',p.id::text,'post_type','notice','is_post_available',true)
    from private.posts p where p.notice_title is not null and p.deleted_at is null and p.hidden_at is null
      and p.created_at>now()-interval '30 days'
      and private.community_author_visible(p.author_id) and private.community_content_visible('post',p.id)
  ) select coalesce(jsonb_agg(e.data order by e.created_at desc,e.key collate "C" desc),'[]')
    from (select * from entries where after_created_at is null or
      (created_at,key collate "C")<(after_created_at,after_key collate "C")
      order by created_at desc,key collate "C" desc limit 20) e);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_community_comments (
  target_post_id   bigint,
  after_created_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  after_id         bigint                   DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if private.get_community_post(target_post_id) is null or exists (select 1 from private.posts p
    where p.id=target_post_id and p.notice_title is not null and p.notice_comments_closed) then return '[]'::jsonb; end if;
  if (after_created_at is null) <> (after_id is null) then
    raise exception 'invalid_comment_cursor' using errcode = '22023';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id::text, 'created_at', c.created_at,
      'content', case when c.author_id is null then null else c.content end,
      'is_post_author', c.author_id = p.author_id,
      'is_mine', c.author_id = (select auth.uid()), 'is_withdrawn', c.author_id is null,
      'anon_number', a.number, 'author_nickname', author.nickname,
      'is_operator', operator.id is not null,
      'vote_choice', vote.choice
    ) order by c.created_at, c.id), '[]'::jsonb)
    from (
      select c.* from private.comments c
      where c.post_id = target_post_id and c.deleted_at is null and c.hidden_at is null
        and private.community_author_visible(c.author_id)
        and private.community_content_visible('comment', c.id)
        and (after_created_at is null or (c.created_at, c.id) > (after_created_at, after_id))
      order by c.created_at, c.id limit 20
    ) c
    join private.posts p on p.id = c.post_id
    left join public.profiles author on author.id = c.author_id
    left join private.post_anon_numbers a on a.post_id = c.post_id and a.user_id = c.author_id
    left join private.admin_users operator on operator.id = c.author_id and operator.disabled_at is null
    left join private.vote_responses vote on p.type = 'vote' and vote.post_id = c.post_id and vote.user_id = c.author_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_community_feed (
  feed_type        text                     DEFAULT 'all'::text,
  after_created_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  after_id         bigint                   DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  viewer_id uuid := (select auth.uid());
begin
  if viewer_id is not null then perform private.assert_account_access(); end if;
  if feed_type not in ('all', 'vote') or feed_type is null or
    ((after_created_at is null) <> (after_id is null)) then
    raise exception 'invalid_feed_cursor' using errcode = '22023';
  end if;
  if viewer_id is not null and not exists (
    select 1 from public.profiles where id = viewer_id and status <> 'suspended'
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
  return (
    select coalesce(jsonb_agg(private.community_post_json(p.id, viewer_id is null)
      order by p.created_at desc, p.id desc), '[]'::jsonb)
    from (
      select p.id, p.created_at from private.posts p
      where p.notice_title is null and p.deleted_at is null and p.hidden_at is null
        and (feed_type = 'all' or p.type = 'vote')
        and private.community_author_visible(p.author_id)
        and private.community_content_visible('post', p.id)
        and (after_created_at is null or (p.created_at, p.id) < (after_created_at, after_id))
      order by p.created_at desc, p.id desc limit 20
    ) p
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_featured_notice()
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if (select auth.uid()) is not null then perform private.assert_account_access(); end if;
  return (select jsonb_build_object('id',p.id::text,'title',p.notice_title) from private.posts p
    where p.notice_title is not null and not p.notice_inbox_only and p.deleted_at is null and p.hidden_at is null
      and private.community_author_visible(p.author_id) and private.community_content_visible('post',p.id)
    order by p.created_at desc,p.id desc limit 1);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_my_community_activity (
  activity_type     text,
  after_activity_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  after_id          bigint                   DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  viewer_id uuid := (select auth.uid());
begin
  perform private.assert_account_access();
  if viewer_id is null then raise exception 'not_authenticated' using errcode = '42501'; end if;
  if not exists (select 1 from public.profiles where id = viewer_id and status <> 'suspended') then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
  if activity_type is null or activity_type not in ('post', 'vote', 'liked') or
     ((after_activity_at is null) <> (after_id is null)) or
     (after_activity_at is not null and (not isfinite(after_activity_at) or after_id <= 0)) then
    raise exception 'invalid_activity_cursor' using errcode = '22023';
  end if;
  if activity_type = 'liked' then
    return (
      select coalesce(jsonb_agg(jsonb_build_object(
        'post', private.community_post_json(page.post_id, false),
        'activity_at', page.created_at, 'activity_id', page.id::text
      ) order by page.created_at desc, page.id desc), '[]'::jsonb)
      from (
        select l.post_id, l.created_at, l.id
        from private.post_likes l join private.posts p on p.id = l.post_id
        where p.notice_title is null and l.user_id = viewer_id and p.type = 'post' and p.deleted_at is null and p.hidden_at is null
          and private.community_author_visible(p.author_id)
          and private.community_content_visible('post', p.id)
          and (after_activity_at is null or (l.created_at, l.id) < (after_activity_at, after_id))
        order by l.created_at desc, l.id desc limit 20
      ) page
    );
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'post', private.community_post_json(page.id, false),
      'activity_at', page.created_at, 'activity_id', page.id::text
    ) order by page.created_at desc, page.id desc), '[]'::jsonb)
    from (
      select p.id, p.created_at from private.posts p
      where p.notice_title is null and p.author_id = viewer_id and p.type = activity_type::public.post_type
        and p.deleted_at is null and p.hidden_at is null and private.community_author_visible(p.author_id)
          and private.community_content_visible('post', p.id)
        and (after_activity_at is null or (p.created_at, p.id) < (after_activity_at, after_id))
      order by p.created_at desc, p.id desc limit 20
    ) page
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.has_unread_notices()
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare viewer_id uuid := private.notification_viewer();
begin
  return exists(select 1 from private.posts p where p.notice_title is not null
    and p.hidden_at is null and p.deleted_at is null and p.created_at>now()-interval '30 days'
    and private.community_author_visible(p.author_id) and private.community_content_visible('post',p.id)
    and p.created_at>coalesce((select c.checked_at from private.notification_checks c where c.user_id=viewer_id),'-infinity'));
end;
$function$;

CREATE OR REPLACE FUNCTION private.normalize_notice()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if new.notice_title is not null then
    new.notice_title := normalize(btrim(new.notice_title), NFC);
    new.content := normalize(btrim(replace(replace(new.content, E'\r\n', E'\n'), E'\r', E'\n')), NFC);
    new.notice_inbox_body := normalize(btrim(new.notice_inbox_body), NFC);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.notice_json (
  target_id bigint
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'id', p.id::text, 'title', p.notice_title, 'body', p.content,
    'inbox_body', p.notice_inbox_body, 'inbox_only', p.notice_inbox_only,
    'comments_closed', p.notice_comments_closed, 'revision', p.notice_revision,
    'is_visible', p.hidden_at is null, 'created_at', p.created_at,
    'is_deleted', p.deleted_at is not null
  ) from private.posts p where p.id = target_id and p.notice_title is not null;
$function$;

CREATE OR REPLACE FUNCTION private.notify_post_commented()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
  actor_nickname text;
begin
  select * into target from private.posts where id = new.post_id;
  if target.notice_title is not null then return new; end if;
  if target.type <> 'post' or target.deleted_at is not null or target.hidden_at is not null or
     new.author_id is null or new.author_id = target.author_id or
     not private.notification_actor_visible(target.author_id, new.author_id) then
    return new;
  end if;
  select nickname into actor_nickname from public.profiles where id = new.author_id;
  insert into private.notifications(recipient_id, type, post_id, actor_id, title, body, event_key)
  values (target.author_id, 'post_commented', target.id, new.author_id, '내 게시글에 댓글이 달렸어요.',
          coalesce(actor_nickname, '사용자') || ': ' || private.notification_text(new.content),
          'comment:' || new.id)
  on conflict (event_key) do nothing;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.notify_post_liked()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
begin
  select * into target from private.posts where id = new.post_id;
  if target.notice_title is not null then return new; end if;
  if target.type <> 'post' or target.deleted_at is not null or target.hidden_at is not null or
     new.user_id is null or new.user_id = target.author_id or
     not private.notification_actor_visible(target.author_id, new.user_id) then
    return new;
  end if;
  insert into private.like_notification_log(post_id, actor_id) values (new.post_id, new.user_id)
  on conflict do nothing;
  if not found then return new; end if;
  insert into private.notifications(recipient_id, type, post_id, actor_id, title, body, event_key)
  values (target.author_id, 'post_liked', target.id, new.user_id, '내 게시글에 좋아요가 달렸어요.',
          '''' || private.notification_text(target.content) || ''' 게시글을 누군가 좋아해요.',
          'like:' || new.post_id || ':' || new.user_id)
  on conflict (event_key) do nothing;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.update_comment (
  target_comment_id bigint,
  comment_content   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  parent_id bigint;
  clean_content text;
begin
  perform private.assert_can_write_community();
  select post_id into parent_id from private.comments where id = target_comment_id and author_id = (select auth.uid());
  if not found then raise exception 'comment_not_found' using errcode = '42501'; end if;
  perform private.lock_community_post_for_write(parent_id);
  if exists(select 1 from private.posts p where p.id=parent_id and p.notice_title is not null and p.notice_comments_closed) then
    raise exception 'notice_comments_closed' using errcode='P0001';
  end if;
  clean_content := private.normalize_comment_content(comment_content);
  update private.comments set content = clean_content, updated_at = now()
  where id = target_comment_id and author_id = (select auth.uid()) and deleted_at is null and hidden_at is null;
  if not found then raise exception 'comment_not_found' using errcode = '42501'; end if;
  return private.community_comment_json(target_comment_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_notice (
  actor         uuid,
  actor_session uuid,
  operation     text,
  target_id     bigint DEFAULT NULL::bigint,
  request_id    uuid   DEFAULT NULL::uuid,
  payload       jsonb  DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  select private.admin_notice(actor,actor_session,operation,target_id,request_id,payload);
$function$;

